[
    ExtensionOf(classStr(whsWorkExecuteDisplayUserDirected))
]
final class AVAwhsWorkExecuteDisplayUserDirectedCls_Extension
{
    #WHSRF
    #AVAWHSRF
    #WHSWorkExecuteDisplayCases
