}

Method.Source:
/// <summary>
/// chain of command methode for displayForm
/// </summary>
/// <param name = "_con">
/// the return display container 
/// </param>
/// <param name = "_buttonClicked">
/// the clicked button
/// </param>
/// <returns>
/// return the new display container
/// </returns>
public container displayForm(container _con, str _buttonClicked)
{
    container       preCon;
    container       retCon;

    preCon =  _con;

    if (!pass.exists(#AVAFullMode)
     && AVAWHSWorkExecuteDisplayHelper::existDisplayContainer(preCon, #Name, #AVAFullMode)
     && AVAWHSWorkExecuteDisplayHelper::getdisplayContainerData(preCon, #Name, #AVAFullMode) != '')
    {
        pass.avaParmFullMode(AVAWHSWorkExecuteDisplayHelper::getdisplayContainerData(preCon, #Name, #AVAFullMode));
        _buttonClicked =  #RFFull;
    }

    using (AVAWorkFullModeIDisposable instance = AVAWorkFullModeIDisposable::construct())
    {
        if (pass.avaParmFullMode()
         && WHSWorkException::avaIsWorkFullLockMode(pass.avaParmFullMode()))
        {
            instance.workFullLockMode = NoYes::Yes;
        }
        else
        {
            instance.workFullLockMode = NoYes::No;
        }

        retCon = next displayForm(preCon, _buttonClicked);

        if (instance
         && instance.finishedSplit == true)
        {
            if (pass.exists(#AVAFullMode))
            {
                pass.remove(#AVAFullMode);
            }
        }
    }

    retCon = this.avaInsertOrderNum(retCon);
    retCon = this.avaInsertWorkTransType(retCon);

    return retCon;

}

/// <summary>
/// chain of command for processButtonClicked
/// </summary>
/// <param name = "_buttonClicked">
/// the clicked button
/// </param>
/// <param name = "_workExecute">
/// the execute class for WhsWorkExecute 
/// </param>
protected void processButtonClicked(str _buttonClicked, WhsWorkExecute _workExecute)
{

    _buttonClicked = this.avaProcessButtonClicked(_buttonClicked, _workExecute);

    next processButtonClicked(_buttonClicked, _workExecute);
}

private str avaProcessButtonClicked(str _buttonClicked, WhsWorkExecute _workExecute)
{
    str                 buttonClicked;
    WHSRFMenuItemTable  menuItemTable = WHSRFMenuItemTable::find(pass.lookup(#MenuItem));

    buttonClicked = _buttonClicked;

    switch (_buttonClicked)
    {
        case #RFFull:
            if (step != 0
                && menuItemTable.AVAWorkFullLockMode == NoYes::Yes
                && !pass.exists(#AVAFullMode))
            {
                if (WHSWorkException::avaHasWorkFullLockMode())
                {
                    step            = #AVASplitWork;
                    buttonClicked   = #AVARFFull;
                }
            }
            break;
        default:
            if (step == #AVASplitWork
                && pass.avaParmFullMode())
            {
                step =  #SplitWork;
            }
    }

    return buttonClicked;
}
